import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DXYAzton.js";import"./chunks/assets.CEP5Mpur.js";var i=JSON.parse(`{"title":"Syllabus | CSCI 497 Senior Project Design","description":"","frontmatter":{},"headers":[],"relativePath":"syllabi/Syllabus_497.md","filePath":"syllabi/Syllabus_497.md","lastUpdated":1785290425000}`),a={name:`syllabi/Syllabus_497.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<figure><img src="/CSCI-Senior-Projects/assets/csu_logo.DSaFiBcI.svg" alt="CSU Logo"></figure><h1 id="syllabus-csci-497-senior-project-design" tabindex="-1">Syllabus | CSCI 497 Senior Project Design <a class="header-anchor" href="#syllabus-csci-497-senior-project-design" aria-label="Permalink to “Syllabus | CSCI 497 Senior Project Design”">​</a></h1><h2 id="general-information" tabindex="-1">General Information <a class="header-anchor" href="#general-information" aria-label="Permalink to “General Information”">​</a></h2><p>Department: Computer Science<br> Course Name: Senior Project Design<br> Course Number: CSCI 497<br> Credit Hours: 1<br> Approved Major Credit: BS in Computer Science, BS in Cybersecurity, BA in Computer and Information Sciences, BT in Computer Science, and BT in Cybersecurity<br> LAC Requirement: None<br> Prerequisites: Permission of the instructor</p><h2 id="course-description" tabindex="-1">Course Description <a class="header-anchor" href="#course-description" aria-label="Permalink to “Course Description”">​</a></h2><p><em>Senior Project Design</em> is the first of a project-based capstone series for the Computer Science degree program. Students will complete the planning, scheduling, and design of a significant project in the field of Computer Science. Upon completion of CSCI 497 Senior Project Design, the student may progress to CSCI 498 Senior Project Construction.</p><h2 id="course-materials" tabindex="-1">Course Materials <a class="header-anchor" href="#course-materials" aria-label="Permalink to “Course Materials”">​</a></h2><p>Additional Materials for Learning</p><ol><li>Computer with basic audio/video output equipment</li><li>Internet access</li><li>A <a href="https://github.com/" target="_blank" rel="noreferrer">GitHub</a> Account</li></ol><h2 id="abet-student-learning-outcomes" tabindex="-1">ABET Student Learning Outcomes <a class="header-anchor" href="#abet-student-learning-outcomes" aria-label="Permalink to “ABET Student Learning Outcomes”">​</a></h2><p>The following student outcomes are to be supported by this coursework:</p><ol start="2"><li><p>An ability to design, implement, and evaluate a computer-based system, process, component, or program to meet desired needs.</p></li><li><p>An ability to communicate effectively with a range of audiences.</p></li><li><p>Recognize professional responsibilities and make informed judgments in computing practice based on legal and ethical principles.</p></li></ol><h2 id="grading" tabindex="-1">Grading <a class="header-anchor" href="#grading" aria-label="Permalink to “Grading”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Objective</th><th>Grade Weight</th></tr></thead><tbody><tr><td style="text-align:right;">Proposal</td><td>60%</td></tr><tr><td style="text-align:right;">Requirements Specification</td><td>40%</td></tr></tbody></table><h2 id="objectives-and-tasks" tabindex="-1">Objectives and Tasks <a class="header-anchor" href="#objectives-and-tasks" aria-label="Permalink to “Objectives and Tasks”">​</a></h2><p>The student must produce a multi-page proposal document and a software requirements specification.</p><h3 id="course-schedule" tabindex="-1">Course Schedule <a class="header-anchor" href="#course-schedule" aria-label="Permalink to “Course Schedule”">​</a></h3><p>The deadline to submit the <strong>final</strong> proposal is noon two weeks before the last day of classes. The proposal is then reviewed by your project advisor and accepted/rejected by the CSCI faculty. Draft proposals are expected to be submitted to the project advisor for review before the final proposal due date.</p><h3 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to “Proposal”">​</a></h3><div class="info custom-block"><p class="custom-block-title">The proposal will contain the following information:</p><ul><li><p>Student Name 👩👨</p></li><li><p>Degree and Major 💻🔑</p></li><li><p>Project Advisor Name 👵👴</p></li><li><p>Expected Graduation Date 📅🏁</p></li><li><p>Problem Statement 💡<br><em>The problem statement should be one or two concise and formal paragraphs containing the following:</em></p><ol><li>Describe the “ideal” state of affairs.</li><li>Explain the problem.</li><li>Explain why the problem is important.</li><li>Back up your assertions.</li><li>Propose your solution (without details).</li><li>Explain the benefits of the solution.</li><li>Conclude by summarizing the problem and solution as your thesis statement.</li></ol><p><em>Use this <a href="https://www.wikihow.com/Write-a-Problem-Statement" target="_blank" rel="noreferrer">wikiHow article</a> for details.</em></p></li><li><p>Project Description 📱</p></li><li><p>Proposed Implementation Language(s) 🐍☕🎯</p></li><li><p>Libraries, Packages, Development Kits, etc. to be used in the proposed implementation languages(s) 🔧</p></li><li><p>Additional Software/Equipment Needed 💻🕹️📱</p></li><li><p>Alternative Solutions and Rationale 🔍</p></li><li><p>Personal Motivation 🍰<br><em>Describes how this project will further the student’s knowledge in the field.</em></p></li><li><p>Outline of Future Research Efforts 📚🚀🧪<br><em>Describes how the student will complete his/her project. What deliverables can be expected?</em></p></li><li><p>Schedule 📆 ⌚<br><em>A list of expected dates various tasks will be completed and deliverables will be submitted to the faculty advisor for CSCI 498 and 499</em></p></li></ul></div><h3 id="requirements-document" tabindex="-1">Requirements Document <a class="header-anchor" href="#requirements-document" aria-label="Permalink to “Requirements Document”">​</a></h3><p>The goal of this assignment is to produce a high-quality Software Requirements Specification (SRS) using the Volere approach, with particular emphasis on writing clear, testable requirements with well-defined fit criteria. This document should describe what the system must do and how well it must do it, without prescribing implementation details.</p><p>The requirements will be of the appropriate subset of the types listed below. For more details about these types and to help generate requirements ideas, request a free educational copy of the <a href="https://www.volere.org/templates/volere-requirements-specification-template/" target="_blank" rel="noreferrer">Volere Requirement Specification Template</a>.</p><h4 id="scope-and-quantity" tabindex="-1">Scope and Quantity <a class="header-anchor" href="#scope-and-quantity" aria-label="Permalink to “Scope and Quantity”">​</a></h4><p>Your requirements document must contain 20 – 50 total requirements that, taken together, provide a complete and coherent description of the system.</p><ul><li>Do not inflate the count with trivial or redundant requirements.</li><li>Each requirement should represent a distinct, necessary stakeholder need.</li><li>A mix of functional and non-functional requirements is expected.</li></ul><h4 id="requirement-types" tabindex="-1">Requirement Types <a class="header-anchor" href="#requirement-types" aria-label="Permalink to “Requirement Types”">​</a></h4><p>Your requirements should be drawn from an appropriate subset of the following Volere requirement types. You are not required to use every type, but you should justify the overall balance based on the nature of your system. There will be more functional requirements than any other type.</p><ol><li><p><a href="https://en.wikipedia.org/wiki/Functional_requirement" target="_blank" rel="noreferrer">Functional</a></p></li><li><p>Look and Feel</p><ol><li>Appearance</li><li>Style</li></ol></li><li><p><a href="https://en.wikipedia.org/wiki/Usability" target="_blank" rel="noreferrer">Usability</a></p><ol><li>Ease of Use</li><li>Personalization and Internationalization</li><li>Learning</li><li>Understandability and Politeness</li><li>Accessibility</li><li>Convenience</li></ol></li><li><p>Performance</p><ol><li>Speed and Latency</li><li>Safety-Critical</li><li>Precision or Accuracy</li><li>Reliability and Availability</li><li>Robustness or Fault-Tolerance</li><li>Capacity</li><li>Scalability or Extensibility</li><li>Longevity</li></ol></li><li><p>Maintainability and Support</p></li><li><p>Security</p><ol><li>Access</li><li>Integrity</li><li>Privacy</li><li>Audit (<em>The information must be recorded to allow security checks,</em> e.g., logs)</li><li>Immunity</li></ol></li><li><p>Cultural</p></li></ol><h4 id="requirement-specification" tabindex="-1">Requirement Specification <a class="header-anchor" href="#requirement-specification" aria-label="Permalink to “Requirement Specification”">​</a></h4><p>Each requirement will contain at least the following information.</p><ol><li><p><strong>ID Number</strong><br> A unique identifier (e.g., FR-01, US-04, SEC-02).</p></li><li><p><strong>Type</strong><br> One of the requirement types listed above.</p></li><li><p><strong>Description</strong><br> A clear, concise statement of <em>what is required</em>.</p><ul><li>Avoid vague terms such as <em>fast</em>, <em>user-friendly</em>, or <em>secure</em> unless they are clarified by the fit criterion.</li><li>Avoid describing implementation or design unless explicitly required.</li></ul></li><li><p><strong>Rationale</strong><br> A brief explanation of <em>why this requirement exists</em>.</p><ul><li>Identify the stakeholder need, business goal, or risk it addresses.</li></ul></li><li><p><strong>Fit Criterion</strong> (Critical)<br> A <strong>measurable and testable condition</strong> that defines how success will be determined.</p><ul><li><p>Ask: <em>How would a tester objectively verify that this requirement has been met?</em></p></li><li><p>Fit criteria may involve thresholds, limits, frequencies, error rates, or test outcomes.</p></li><li><p>If a requirement cannot be tested, it is not yet complete.</p></li></ul></li><li><p><strong>Priority</strong><br> An indication of importance (e.g., High / Medium / Low, or Must / Should / Could).</p></li><li><p><strong>Dependencies</strong><br> The ID(s) of any other requirement(s) that must be satisfied before this one can be implemented or verified (if applicable).</p></li></ol><h4 id="quality-expectations" tabindex="-1">Quality Expectations <a class="header-anchor" href="#quality-expectations" aria-label="Permalink to “Quality Expectations”">​</a></h4><p>High-quality requirements are:</p><ul><li><p><strong>Precise</strong> – stated clearly, with no unnecessary wording</p></li><li><p><strong>Unambiguous</strong> – interpreted the same way by all readers</p></li><li><p><strong>Testable</strong> – validated through the fit criterion</p></li><li><p><strong>Describe real needs</strong> – traceable to a real stakeholder or system need</p></li><li><p><strong>Solution-independent</strong> – focused on what, not how</p></li></ul><p>You should assume that your document will be used by developers, testers, and project managers who were not involved in writing it.</p><h2 id="attendance" tabindex="-1">Attendance <a class="header-anchor" href="#attendance" aria-label="Permalink to “Attendance”">​</a></h2><p>The student is expected to schedule a meeting with the project advisor within the first full week of the class. During this initial meeting, the attendance policies will be discussed and meeting times will be scheduled between the student and advisor.</p><h2 id="course-department-and-university-policies" tabindex="-1">Course, Department, and University Policies <a class="header-anchor" href="#course-department-and-university-policies" aria-label="Permalink to “Course, Department, and University Policies”">​</a></h2><h3 id="academic-integrity-and-the-honor-code" tabindex="-1">Academic Integrity and the Honor Code <a class="header-anchor" href="#academic-integrity-and-the-honor-code" aria-label="Permalink to “Academic Integrity and the Honor Code”">​</a></h3><p>All students are expected to adhere to <a href="https://www.charlestonsouthern.edu/wp-content/uploads/Policy-R-58-updated-November-2025.pdf" target="_blank" rel="noreferrer">Charleston Southern University&#39;s Academic Integrity Policy</a> and the <a href="/CSCI-Senior-Projects/integrity">Computer Science Departmental Guidelines</a>. For example, all work must be original and must not be copied from another student. Failure to follow this guideline will be considered a violation of the code and will be treated accordingly. Students are encouraged to ask their instructor(s) for clarification regarding their academic dishonesty standards.</p><h3 id="ai-policy-for-csci-497" tabindex="-1">AI Policy for CSCI 497 <a class="header-anchor" href="#ai-policy-for-csci-497" aria-label="Permalink to “AI Policy for CSCI 497”">​</a></h3><p><strong>Level 1. Use of generative AI is <em>prohibited</em> in this course.</strong></p><p>To ensure development and mastery of the concepts and skills in this course, the use of generative artificial intelligence (AI) tools is prohibited. Students who are unsure of this policy or any assignment-specific directions, including whether a given technology is considered AI, should consult the course instructor before using such technology to complete their assignment.</p><p>While proper AI use is an important skill that will be emphasized in other courses, AI misuse short-circuits the learning process to give the illusion of proficiency without the necessary depth. It is unethical to take full credit for work created with the help of AI. This principle is the same as using someone else’s idea without citing it.</p><p><a href="/CSCI-Senior-Projects/integrity#artificial-intelligence-ai">Review the departmental policies for AI use in Computer Science coursework.</a></p><h3 id="course-evaluations" tabindex="-1">Course Evaluations <a class="header-anchor" href="#course-evaluations" aria-label="Permalink to “Course Evaluations”">​</a></h3><p>To pursue our mission of <em>Academic Excellence in a Christian Environment</em>, we must receive feedback from students. The student-feedback survey is online and will be available to students in the second half of the semester. Students are strongly encouraged to complete the short evaluation survey, which is anonymous. Your professor will let you know when the survey is available. The survey will be available through your MyCSU account. We greatly value your opinion!</p><h3 id="student-representatives" tabindex="-1">Student Representatives <a class="header-anchor" href="#student-representatives" aria-label="Permalink to “Student Representatives”">​</a></h3><p>These are students who are designated by letter to represent the University in official business (e.g., athletic, music, and similar events). If officially scheduled absences cause these students to miss tests, assignments, or similar academic activities, university policy allows these to be made up without penalty. Student Representatives may opt to either make-up tests <em>before</em> departure or supplant missed tests with the final exam grade. Final exams must always be taken <em>before</em> departure to avoid an Incomplete for the course. Scheduled assignments remain subject to the lateness policy and must be turned in before departure to avoid lateness penalties. Student Representatives are responsible for informing the instructor of official absences and to make all appropriate arrangements.</p><h3 id="internet-etiquette" tabindex="-1">Internet Etiquette <a class="header-anchor" href="#internet-etiquette" aria-label="Permalink to “Internet Etiquette”">​</a></h3><p>Charleston Southern University (CSU) holds students, faculty, and staff to the highest standards of conduct and expects all to demonstrate courteous behaviors and practices in online communications. This policy includes guidelines and recommendations for online communications. Being respectful, thoughtful, meaningful, and ethical are fundamental to good netiquette.</p><p>CSU&#39;s basic netiquette rules are:</p><ul><li>Course communications are for internal use only and are considered confidential. Do not forward or quote discussion posts, emails, or other course communications to outside parties.</li><li>Never share personal login usernames, IDs, or passwords.</li><li>Do not type in all capital letters. It is perceived online as shouting.</li><li>Use proper capitalization, grammar, spelling, and punctuation conventions for professional communications.</li><li>Avoid texting jargon or abbreviations without explanation. <ul><li>Incorrect: &quot;CSU is a wonderful university.&quot;</li><li>Correct: &quot;Charleston Southern University (CSU) is a wonderful university.&quot;</li></ul></li><li>Be mindful of sending emails. Ensure that content is relevant and pay attention to <em>Reply</em> versus <em>Reply All</em>.</li><li>BucMail is the only email allowed for course communications. Other platforms (Yahoo, Gmail, etc.) are prohibited.</li><li>In video conferencing, mute your microphone when not speaking.</li><li>Differing views are natural and welcome in discussion boards. Be respectful in your comments - even if you disagree or dislike someone&#39;s position on a topic.</li><li>Respect the time and availability of students, faculty, and staff. Emails should be addressed within 24 hours of receipt. Keep in mind that traditional faculty work hours are 8 a.m. - 5 p.m. EST.</li></ul><h2 id="accessibility-services" tabindex="-1">Accessibility Services <a class="header-anchor" href="#accessibility-services" aria-label="Permalink to “Accessibility Services”">​</a></h2><p>Any student who may need accommodations should review the requirements/procedures on the <a href="https://www.charlestonsouthern.edu/academics/student-success/accessibility-services/" target="_blank" rel="noreferrer">Accessibility Services website</a>. Once approved to receive accommodations, the student must contact the instructor.</p><h3 id="title-ix-confidentiality-and-responsible-employee-statement" tabindex="-1">Title IX: Confidentiality and Responsible Employee Statement <a class="header-anchor" href="#title-ix-confidentiality-and-responsible-employee-statement" aria-label="Permalink to “Title IX: Confidentiality and Responsible Employee Statement”">​</a></h3><p>Charleston Southern University is committed to maintaining a safe learning environment for everyone. In accordance with Title IX of the Education Amendments of 1972, the university prohibits any form of sexual harassment, including quid pro quo harassment, hostile environments, sexual assault, dating/domestic violence, and stalking. This policy applies to all students, employees, and visitors.</p><p>Additionally, Title IX prohibits discrimination against students based on pregnancy, childbirth, false pregnancy, termination of pregnancy, or recovery from these conditions. Pregnant or parenting students may receive accommodations to ensure their full participation in educational programs. These adjustments can be arranged through the university’s Title IX Coordinator or their designee.</p><p>Under Charleston Southern University’s Title IX Policy, all faculty members, including teaching assistants, are required to report any disclosures of sex or gender-based discrimination or violence to the Title IX Coordinator. The Title IX Coordinator will provide support and resources while maintaining privacy. If you or someone you know needs assistance, please contact the Title IX Coordinator:</p><p><strong>Summer Cora</strong><br> (843)-863-7374<br><a href="mailto:titleix@csuniv.edu" target="_blank" rel="noreferrer">titleix@csuniv.edu</a><br> Office Location: 2nd floor of the Student Center</p><p>Please visit the <a href="https://www.charlestonsouthern.edu/offices/title-ix/" target="_blank" rel="noreferrer">CSU Title IX webpage</a> here for more information on Title IX procedures, anonymous reporting, or available support.</p><hr><p>See all course, department, and university policies located in <a href="https://csuniv.blackboard.com" target="_blank" rel="noreferrer">Blackboard</a> and the <a href="https://www.charlestonsouthern.edu/current-students/student-resources/" target="_blank" rel="noreferrer">CSU Student Handbook</a>.</p>`,64)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};